package com.bank.remarkcodec;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Serializes transaction remarks reversibly for National Bank of India.
public class RemarkCodec {
    private static final Logger log = Logger.getLogger(RemarkCodec.class.getName());
    private static final char SEP = '#';          // separator between length and content

    // Encode: length + '#' + raw content for each remark. O(total chars).
    public String encode(List<String> remarks) {
        StringBuilder sb = new StringBuilder();
        for (String r : remarks) {
            sb.append(r.length()).append(SEP).append(r); // content never escaped
        }
        String payload = sb.toString();
        log.info(() -> "Encoded payload = " + payload);
        return payload;
    }

    // Decode: read length, skip '#', read exactly that many chars. O(total chars).
    public List<String> decode(String payload) {
        List<String> out = new ArrayList<>();
        int i = 0;
        while (i < payload.length()) {
            int sep = payload.indexOf(SEP, i);     // find separator ending the length
            int len = Integer.parseInt(payload.substring(i, sep));
            int start = sep + 1;                   // content starts after separator
            out.add(payload.substring(start, start + len)); // read exactly len chars
            i = start + len;                       // advance past content
        }
        log.info(() -> "Decoded " + out.size() + " remarks");
        return out;
    }
}
