package com.bank.remarkcodec;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: round-trip remarks including awkward characters.
public class RemarkCodecDemo {
    private static final Logger log = Logger.getLogger(RemarkCodecDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        RemarkCodec codec = new RemarkCodec();

        // Remarks include a comma, a '#', and an empty string.
        List<String> remarks = List.of("Rent", "EMI,HDFC", "fee#2", "");
        String payload = codec.encode(remarks);
        List<String> back = codec.decode(payload);

        log.info(() -> "Round-trip equal = " + remarks.equals(back));
        log.info(() -> "Recovered = " + back);
    }
}
